package ai.eva.android.probe;
import android.app.Activity;import android.content.Context;import android.media.*;import android.graphics.Bitmap;import org.json.*;import java.io.*;
/** Explicit synthetic fixture checks only; no user file traversal or cloud calls. */
final class DocumentPreviewProbe {
 static void check(Activity owner,String folder){new Thread(()->{JSONObject out=new JSONObject();try{if(folder==null||!folder.matches("preview-checks-[a-f0-9]{12}"))throw new IOException("Invalid fixture scope");File root=WorkspaceFiles.resolve(owner,folder);String word=DocumentPreview.renderOffice(new File(root,"sample.docx")),excel=DocumentPreview.renderOffice(new File(root,"sample.xlsx")),ppt=DocumentPreview.renderOffice(new File(root,"sample.pptx"));if(!word.contains("课程预览")||!word.contains("data:image/png;base64,")||!excel.contains("课程预算")||!ppt.contains("第一张幻灯片"))throw new IOException("Native Office parser mismatch");out.put("office",true);boolean rejected=false;try{DocumentPreview.renderOffice(new File(root,"unsafe.docx"));}catch(Exception e){rejected=true;}if(!rejected)throw new IOException("DOCTYPE accepted");out.put("xmlSafety",true);
 MediaPlayer audio=new MediaPlayer();try{audio.setVolume(0,0);audio.setDataSource(new File(root,"sample.wav").getPath());audio.prepare();if(audio.getDuration()<900)throw new IOException("Audio duration mismatch");audio.start();Thread.sleep(120);if(!audio.isPlaying())throw new IOException("Audio not playing");audio.pause();if(audio.isPlaying())throw new IOException("Audio did not pause");out.put("audioPlaybackPause",true);}finally{audio.release();}
 MediaMetadataRetriever video=new MediaMetadataRetriever();try{video.setDataSource(new File(root,"sample.webm").getPath());Bitmap frame=video.getFrameAtTime(0);if(frame==null)throw new IOException("Video decode unavailable");out.put("videoWidth",frame.getWidth()).put("videoHeight",frame.getHeight());frame.recycle();}finally{video.release();}out.put("passed",true);
 }catch(Exception e){try{out.put("passed",false).put("error",e.toString());}catch(Exception ignored){}}owner.getSharedPreferences("eva-preview-check",0).edit().putString("result",out.toString()).commit();android.util.Log.i("EvaPreviewCheck",out.toString());},"eva-preview-fixture-check").start();}
}
